//! 🔢️ Each default array element is produced and published under its own actual bounded turn.
use super::*;
use std::mem::{MaybeUninit,size_of};
pub struct NativeArrayDefaultCursor<T:NativeDefault,const N:usize>where[T;N]:RetireOwned{child:NativeDefaultSlot<T>,rows:ManuallyDrop<MaybeUninit<[T;N]>>,pending:ManuallyDrop<Option<T>>,output:ManuallyDrop<Option<[T;N]>>,retirement:RetainedCloneClose,index:usize,initialized:usize,phase:u8,closing:bool,failed:bool}
impl<T:NativeDefault,const N:usize>NativeArrayDefaultCursor<T,N>where[T;N]:RetireOwned{pub fn new()->Self{Self{child:NativeDefaultSlot::new(),rows:ManuallyDrop::new(MaybeUninit::uninit()),pending:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),index:0,initialized:0,phase:0,closing:false,failed:false}}}
impl<T:NativeDefault,const N:usize>NativeDefault for[T;N]where[T;N]:RetireOwned{type Cursor=NativeArrayDefaultCursor<T,N>;fn default_cursor()->Self::Cursor{NativeArrayDefaultCursor::new()}}
impl<T:NativeDefault,const N:usize>NativeDefaultCursor<[T;N]>for NativeArrayDefaultCursor<T,N>where[T;N]:RetireOwned{
 fn demands(&self,body:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}if self.failed{return Ok(Default::default())}match self.phase{0|4|6|7=>Ok(fixed(0)),1=>if self.child.ready(){Ok(fixed(0))}else{self.child.demands(body,maximum_work_units)},2=>Ok(fixed(size_of::<T>())),3=>if self.child.terminal_is_empty(){Ok(fixed(0))}else{self.child.close_demands(body)},_=>Err(invalid())}}
 fn advance(&mut self,control:&mut NativeDecodeControl<'_>,body:usize,maximum_work_units:u64,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{semio_framework_value_native_receiver_protocol::native_receive_zero_work!(maximum_work_units);
  if self.failed{return RetainedWorkOutcome{result:Err(invalid().into()),work:0}}if self.output_ready(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let d=match self.demands(body,maximum_work_units){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if let Err(e)=control.checkpoint(){return RetainedWorkOutcome{result:Err(e.into()),work:0}}
  if self.phase==1{if self.child.ready(){let turn=self.child.take(g);let result=turn.result.and_then(|value|{let Some((value,p))=value else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.pending=Some(value);self.phase=2;Ok(RetainedCloneStep::Progress(p))});return RetainedWorkOutcome{result:result.map_err(Into::into),work:turn.work}}let turn=self.child.advance(control,body,maximum_work_units,g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())),work:turn.work}}
  if self.phase==3&&!self.child.terminal_is_empty(){let turn=self.child.close_step(g);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into),work:turn.work}}
  let mut p=receipt(fixed(0));let result=(||{match self.phase{0=>{if N==0{self.failed=true;return Err(invalid().with_retained_progress(p))}self.phase=1;},2=>{if self.index>=N||self.pending.is_none(){return Err(invalid().with_retained_progress(p))}let value=self.pending.take().ok_or_else(||ValueError::invariant("pending absent"))?;unsafe{self.rows.as_mut_ptr().cast::<T>().add(self.index).write(value)}self.initialized+=1;self.index+=1;self.child.begin_close();self.phase=3;p.copied_bytes=size_of::<T>();},3=>self.phase=4,4=>{self.child=NativeDefaultSlot::new();self.phase=if self.index==N{6}else{1};},6=>{if self.initialized!=N{return Err(invalid().with_retained_progress(p))}*self.output=Some(unsafe{self.rows.as_ptr().read()});self.initialized=0;self.phase=7;},_=>return Err(invalid().with_retained_progress(p))}Ok(if self.output_ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})})();control.receive_retained_work(g,RetainedWorkOutcome{result,work:1})
 }
 fn output_ready(&self)->bool{!self.closing&&self.phase==7&&self.output.is_some()}
 semio_framework_value_native_receiver_protocol::native_owned_output!([T;N],invalid);
 fn begin_close(&mut self){self.closing=true;self.child.begin_close();}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if !self.child.terminal_is_empty(){return self.child.close_demands(body)}if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.pending.is_some(){return self.retirement.next_owner_demands::<T>(true,&None,body)}if self.initialized>0{return Ok(fixed(0))}if self.output.is_some(){return self.retirement.next_owner_demands::<[T;N]>(true,&None,body)}Ok(Default::default())}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}if !self.child.terminal_is_empty(){return self.child.close_work_demand(body)}if !self.retirement.is_empty(){return self.retirement.next_owner_work::<()>(false,&None,body)}if self.pending.is_some(){return self.retirement.next_owner_work::<T>(true,&None,body)}if self.initialized>0{return Ok(1)}self.retirement.next_owner_work::<[T;N]>(self.output.is_some(),&None,body)}
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementOutcome{let g=effect.grant();if self.terminal_is_empty(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}if !self.child.terminal_is_empty(){let turn=self.child.close_step(&mut effect.reborrow(g,effect.maximum_work_units()).expect("retirement child exceeds original effect"));return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into),work:turn.work}}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(effect);return RetainedWorkOutcome{result:turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into),work:turn.work}}if self.pending.is_some(){let turn=self.retirement.begin_granted(&mut self.pending,effect);return RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work}}if self.initialized>0{self.initialized-=1;*self.pending=Some(unsafe{self.rows.as_ptr().cast::<T>().add(self.initialized).read()});return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(receipt(fixed(0)))),work:1}}let turn=self.retirement.begin_granted(&mut self.output,effect);RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:turn.work}}
 fn terminal_is_empty(&self)->bool{self.child.terminal_is_empty()&&self.initialized==0&&self.pending.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
}
impl<T:NativeDefault,const N:usize>Drop for NativeArrayDefaultCursor<T,N>where[T;N]:RetireOwned{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native default array requires funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.rows);ManuallyDrop::drop(&mut self.pending);ManuallyDrop::drop(&mut self.output);}}}}
